//! ACL insertion and SID-and-attributes array copy routines.
use super::acl::{RtlAcl,RtlAceHeader};
use super::sid::SidHeader;
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;const BAD_ACL:i32=0xC0000077u32 as i32;
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_ace(acl:*mut RtlAcl,revision:u32,start_index:u32,list:*const u8,list_len:u32)->i32{if acl.is_null()||(list_len>0&&list.is_null())||!(revision==2||revision==4)||unsafe{(*acl).size<8}{return INVALID;}let a=unsafe{&mut *acl};let mut existing=8usize;for _ in 0..a.ace_count{if existing+4>a.size as usize{return BAD_ACL;}let h=unsafe{&*((acl as *const u8).add(existing) as *const RtlAceHeader)};if h.ace_size<4||h.ace_size%4!=0||existing+h.ace_size as usize>a.size as usize{return BAD_ACL;}existing+=h.ace_size as usize;}let mut addn=0usize;let mut p=0usize;while p<list_len as usize{if p+4>list_len as usize{return INVALID;}let h=unsafe{&*((list.add(p)) as *const RtlAceHeader)};if h.ace_size<4||h.ace_size%4!=0||p+h.ace_size as usize>list_len as usize{return INVALID;}p+=h.ace_size as usize;addn+=1;}if p!=list_len as usize||existing+list_len as usize>a.size as usize{return SMALL;}let idx=if start_index==u32::MAX{a.ace_count as usize}else{start_index as usize};if idx>a.ace_count as usize{return INVALID;}let mut insert=8usize;for _ in 0..idx{let h=unsafe{&*((acl as *const u8).add(insert) as *const RtlAceHeader)};insert+=h.ace_size as usize;}unsafe{core::ptr::copy((acl as *const u8).add(insert),(acl as *mut u8).add(insert+list_len as usize),existing-insert);core::ptr::copy(list,(acl as *mut u8).add(insert),list_len as usize);}a.ace_count=a.ace_count.saturating_add(addn.min(u16::MAX as usize) as u16);SUCCESS}
#[repr(C)] pub struct SidAndAttributes{pub sid:*mut SidHeader,pub attributes:u32}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_copy_sid_and_attributes_array(count:u32,src:*const SidAndAttributes,sid_area_size:u32,dst:*mut SidAndAttributes,sid_area:*mut u8,remaining_area:*mut *mut core::ffi::c_void,remaining_size:*mut u32)->i32{if count>0&&(src.is_null()||dst.is_null()){return INVALID;}if remaining_area.is_null()||remaining_size.is_null()||(sid_area_size>0&&sid_area.is_null()){return INVALID;}let mut used=0usize;for i in 0..count as usize{let s=unsafe{&*src.add(i)};let n=(unsafe{super::sid::rtl_length_sid(s.sid)}) as usize;if n==0{return INVALID;}used=(used+3)&!3;if used.checked_add(n).is_none_or(|v|v>sid_area_size as usize){unsafe{*remaining_area=sid_area.add(used.min(sid_area_size as usize)) as *mut core::ffi::c_void;*remaining_size=sid_area_size.saturating_sub(used.min(sid_area_size as usize) as u32);}return SMALL;}used+=n;}let mut off=0usize;for i in 0..count as usize{let s=unsafe{&*src.add(i)};let n=unsafe{super::sid::rtl_length_sid(s.sid)} as usize;off=(off+3)&!3;unsafe{core::ptr::copy_nonoverlapping(s.sid as *const u8,sid_area.add(off),n);(*dst.add(i)).sid=sid_area.add(off) as *mut SidHeader;(*dst.add(i)).attributes=s.attributes;}off+=n;}unsafe{*remaining_area=sid_area.add(off) as *mut core::ffi::c_void;*remaining_size=sid_area_size.saturating_sub(off as u32);}SUCCESS}
